def transform(grid):
    out = []
    for br in range(0, len(grid), 3):
        row = []
        for bc in range(0, len(grid[0]), 3):
            counts = {}
            for r in range(br, min(br + 3, len(grid))):
                for c in range(bc, min(bc + 3, len(grid[0]))):
                    color = grid[r][c]
                    if color != 5:
                        counts[color] = counts.get(color, 0) + 1
            row.append(max(counts, key=counts.get) if counts else 5)
        out.append(row)
    return out
